// Deterministic checks + routing. The LLM only extracts; code decides.
const files = $('Split documents').all();
const CONF_MIN = 0.75;
const MIN_SAVED_PER_AUTO_DOC = 8; // assumption: manual intake/data entry minutes per document (tune with ops baseline)
const npiValid = n => { // CMS NPI check digit (Luhn with 80840 prefix)
  n = String(n || '').replace(/\D/g, ''); if (!/^\d{10}$/.test(n)) return false;
  let sum = 24; const b = n.slice(0, 9);
  for (let i = 0; i < 9; i++) { let v = +b[8 - i]; if (i % 2 === 0) { v *= 2; if (v > 9) v -= 9; } sum += v; }
  return (10 - (sum % 10)) % 10 === +n[9];
};
const isoDate = d => { if (!d) return null; const s = String(d).trim(); if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const t = new Date(s); if (isNaN(t)) return null; return t.getFullYear() + '-' + String(t.getMonth() + 1).padStart(2, '0') + '-' + String(t.getDate()).padStart(2, '0'); };
const ICD10 = /^[A-TV-Z][0-9][0-9AB](\.?[0-9A-TV-Z]{1,4})?$/i;
const ref = s => { let h = 2166136261; for (const c of s) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return 'P-' + (h >>> 0).toString(16).toUpperCase(); };
const REQUIRED = {
  new_prescription: ['patient.first_name', 'patient.last_name', 'patient.dob', 'medication.name', 'prescriber.name', 'prescriber.npi'],
  prior_authorization: ['patient.first_name', 'patient.last_name', 'patient.dob', 'medication.name', 'prescriber.npi', 'diagnosis_icd10', 'insurance.payer', 'insurance.member_id'],
  insurance_card: ['patient.first_name', 'patient.last_name', 'insurance.payer', 'insurance.member_id'],
  patient_message: [], other: []
};
const get = (o, p) => p.split('.').reduce((a, k) => (a == null ? null : a[k]), o);
return $input.all().map((item, i) => {
  const f = files[i].json; const issues = []; let x = {};
  try { const t = String(item.json.text || ''); x = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); }
  catch (e) { issues.push('AI output was not valid JSON'); }
  const docType = REQUIRED[x.doc_type] ? x.doc_type : 'other';
  const conf = typeof x.confidence === 'number' ? x.confidence : 0;
  const missing = (REQUIRED[docType] || []).filter(p => get(x, p) == null || get(x, p) === '');
  if (missing.length) issues.push('missing: ' + missing.join(', '));
  const npi = get(x, 'prescriber.npi'); const npiOk = npi ? npiValid(npi) : null;
  if (npi && !npiOk) issues.push('prescriber NPI ' + npi + ' fails CMS check digit');
  const dob = isoDate(get(x, 'patient.dob'));
  if (get(x, 'patient.dob') && !dob) issues.push('unreadable date of birth');
  if (dob) { const age = (Date.now() - new Date(dob)) / 3.15576e10; if (age < 0 || age > 120) issues.push('implausible date of birth ' + dob); }
  if (x.diagnosis_icd10 && !ICD10.test(String(x.diagnosis_icd10).trim())) issues.push('ICD-10 code ' + x.diagnosis_icd10 + ' has invalid format');
  if (conf < CONF_MIN) issues.push('low AI confidence ' + conf);

  // Routing
  let queue, next;
  const dataProblem = missing.length || npiOk === false || issues.some(s => /date of birth|ICD-10/.test(s));
  if (issues.some(s => /not valid JSON|low AI confidence/.test(s)) || docType === 'other') { queue = 'manual_review'; next = 'Intake specialist reviews document and classifies manually'; }
  else if (dataProblem) { queue = 'missing_info_outreach'; next = 'Send outreach to prescriber office for: ' + issues.join('; '); }
  else if (docType === 'prior_authorization') { queue = 'prior_authorization'; next = 'Submit PA to ' + get(x, 'insurance.payer') + (x.urgency === 'urgent' ? ' (URGENT, expedited review)' : ''); }
  else if (docType === 'new_prescription' || docType === 'insurance_card') { queue = 'benefits_verification'; next = docType === 'insurance_card' ? 'Attach coverage to patient profile and run benefits check' : 'Run benefits verification' + (get(x, 'insurance.member_id') ? '' : ' (request insurance card from patient)'); }
  else { queue = 'customer_care'; next = 'Customer care ticket: ' + (x.summary || 'patient message'); }

  // Status updates from fixed templates (no AI-written promises, minimum necessary PHI)
  const first = get(x, 'patient.first_name') || 'there';
  const initials = ((get(x, 'patient.first_name') || '?')[0] + (get(x, 'patient.last_name') || '?')[0]).toUpperCase();
  const med = get(x, 'medication.name') || 'your medication';
  const msg = {
    benefits_verification: 'Hi ' + first + ', we received your prescription for ' + med + ' and are verifying your insurance benefits. We will update you within 1 business day.',
    prior_authorization: 'Prior authorization request received for patient ' + initials + ' (' + med + '). It is now in our PA queue; we will notify your office of the payer decision.',
    missing_info_outreach: 'We received a document for patient ' + initials + ' but cannot proceed until we have: ' + (missing.join(', ') || issues.join('; ')) + '. Please reply or re-fax with the corrected information.',
    manual_review: 'Internal: document needs manual classification by an intake specialist.',
    customer_care: 'Hi ' + first + ', thanks for your message. A care team member will reply within 1 business day.'
  }[queue];
  const name = [get(x, 'patient.first_name'), get(x, 'patient.last_name')].filter(Boolean).join(' ');
  return { json: {
    case_id: f.case_id, received_at: f.received_at, file_name: f.file_name, doc_type: docType, confidence: conf,
    queue, next_action: next, patient_name: name || null, patient_dob: dob, patient_ref: name ? ref((name + '|' + (dob || '')).toLowerCase()) : null,
    medication: [get(x, 'medication.name'), get(x, 'medication.strength')].filter(Boolean).join(' ') || null,
    prescriber_name: get(x, 'prescriber.name'), prescriber_npi: npi ? String(npi) : null, npi_valid: npiOk,
    payer: get(x, 'insurance.payer'), member_id: get(x, 'insurance.member_id') ? String(get(x, 'insurance.member_id')) : null,
    diagnosis_icd10: x.diagnosis_icd10 || null, issues: issues.join('; '), status_message: msg, extracted_json: JSON.stringify(x)
  }};
});

// KPI / observability row per document. No PHI: only case_id and metrics.
const files = $('Split documents').all();
const ocr = $('OCR + layout (Docling)').all();
const llm = $('Classify + extract (LLM)').all();
const MIN_SAVED_PER_AUTO_DOC = 8;
const SYSTEM_PROMPT_CHARS = 1100;
return $input.all().map((item, i) => {
  const c = item.json; const auto = c.queue !== 'manual_review';
  const md = (ocr[i] && ocr[i].json.document && ocr[i].json.document.md_content) || '';
  return { json: {
    case_id: c.case_id, run_at: new Date().toISOString(), doc_type: c.doc_type, queue: c.queue,
    auto_routed: auto, needs_human: c.queue === 'manual_review' || c.queue === 'missing_info_outreach',
    issue_count: c.issues ? c.issues.split('; ').length : 0, confidence: c.confidence,
    processing_ms: Date.now() - files[i].json.received_ms,
    est_input_tokens: Math.round((md.length + SYSTEM_PROMPT_CHARS) / 4),
    est_output_tokens: Math.round(String((llm[i] && llm[i].json.text) || '').length / 4),
    model: 'groq/openai/gpt-oss-120b', est_minutes_saved: auto ? MIN_SAVED_PER_AUTO_DOC : 0
  }};
});
